using System.Text.Json;
using System.Text.Json.Serialization;
using System.Text.Json.Serialization.Metadata;

// Options with the default reflection-based resolver – knows about any type.
var webOptions = new JsonSerializerOptions(JsonSerializerDefaults.Web);

// 1) GetTypeInfo<T>() — returns a strongly-typed JsonTypeInfo<T> directly.
JsonTypeInfo<WeatherForecast> typedInfo = webOptions.GetTypeInfo<WeatherForecast>();
Console.WriteLine($"GetTypeInfo<WeatherForecast> → Type = {typedInfo.Type.Name}");

var forecast = new WeatherForecast("Seattle", 18.5);
string json = JsonSerializer.Serialize(forecast, typedInfo);
Console.WriteLine($"Serialized: {json}");

// 2) TryGetTypeInfo<T>() — probe without throwing.
//    With the default resolver every type succeeds:
if (webOptions.TryGetTypeInfo<WeatherForecast>(out var info))
    Console.WriteLine($"TryGetTypeInfo<WeatherForecast> succeeded → {info!.Type.Name}");

// Now use options whose resolver (a source-gen context) only knows
// about WeatherForecast — asking for an unknown type returns false.
var limitedOptions = new JsonSerializerOptions
{
    TypeInfoResolver = AppJsonContext.Default
};

if (limitedOptions.TryGetTypeInfo<WeatherForecast>(out var found))
    Console.WriteLine($"TryGetTypeInfo<WeatherForecast> on limited context → found ({found!.Type.Name})");

if (limitedOptions.TryGetTypeInfo<UnknownType>(out var notFound))
    Console.WriteLine("This should not print");
else
    Console.WriteLine($"TryGetTypeInfo<UnknownType> on limited context → not found (returned false, no exception)");

// --- Types ----------------------------------------------------------------
public record WeatherForecast(string City, double TempC);
public record UnknownType(int Id);

[JsonSerializable(typeof(WeatherForecast))]   // only WeatherForecast is registered
internal partial class AppJsonContext : JsonSerializerContext;

